          onMouseMove={handleMouseMove}
          onMouseLeave={handleMouseLeave}
          onClick={handleClick}
          onTouchEnd={handleTouchEnd}
        />
        <VictoryOverlay
          show={victoryVisible}
          winner={winner}
          isDraw={isDraw}
          lastHash={lastHash}
